      '<div class="lbl">地址 <span class="faint">可不填</span></div><input type="text" id="pc-mm-url" autocomplete="off" placeholder="留空 = 国内 api.minimaxi.com" value="' + esc(fv(form, 'mmUrl', set.mmUrl || '')) + '">' +
      '<div class="lbl">模型</div><select id="pc-mm-model">' + opts(MM_MODELS, fv(form, 'mmModel', set.mmModel || (mc && mc.model) || 'speech-02-turbo')) + '</select>' +
      '<div class="hint">登录 MiniMax 开放平台 → 账户管理 → 接口密钥，新建一个复制过来。国内账号地址留空；海外 minimax.io 的账号地址填 https://api.minimax.io。' + esc(srcTxt(mc, 'MiniMax')) + '</div>';
