        if (!C.tierOk(c.tier, sc.tier)) why.push(who + ' 只接到「' + c.tier + '」，这部是「' + sc.tier + '」');
        var left = C.daysToShoot(c, st.day); if (left > 0) why.push(who + ' 今天才签的约，' + C.mdShort(C.canShootDay(c)) + ' 起才能进棚');
