    var h = '<div class="eb">OFFERS</div><h2 class="h">片约</h2><div class="sub" style="margin-bottom:10px">银星、鼎盛、唯粉那边的创作者找上门。片酬看名气、尺度和片商；每天过去会来新的。' + (A.guarantee ? '<br><b>保底合同</b>：' + esc(A.guarantee.studio) + ' 每周两场（每周一自动排）。' : '连着 ' + E.guaranteeAfter + ' 场收尾都稳，片商会来谈保底。') + '</div>';
    h += open.length ? open.map(function (g) { return gigCard(g, st); }).join('') : '<div class="empty">现在没人找你。过一天就会有。</div>';
    if (acc.length) h += '<h3 class="h3">接了的</h3>' + acc.map(function (g) { return gigCard(g, st); }).join('');
